<script>function candidateForm(i={}){return{kategori:i.kategori||'L',ketua:i.ketua||null,wakil:i.wakil||null,students:[],search:{ketua:'',wakil:''},open:{ketua:false,wakil:false},loading:false,uploading:false,status:'',progress:0,error:'',photoKey:'',preview:null,async init(){await this.load()},async load(){this.loading=true;try{let r=await fetch(`{{route('pilketos.kandidat.lookup')}}?periode_id={{$periode?->id}}&kategori=${this.kategori}`,{headers:{Accept:'application/json'}}),p=await r.json();if(!r.ok)throw Error(p.message);this.students=p.data;for(let x of ['ketua','wakil'])if(this[x]&&!this.students.some(s=>+s.nis===+this[x]))this[x]=null}catch(e){this.error=e.message||'Gagal memuat siswa.'}finally{this.loading=false}},changeCategory(){this.ketua=this.wakil=null;this.load()},list(x){let q=this.search[x].toLowerCase(),o=this[x==='ketua'?'wakil':'ketua'];return this.students.filter(s=>(!o||+s.nis!==+o)&&(!q||s.name.toLowerCase().includes(q)||String(s.nis).includes(q)))},label(s){return s?`${s.name} — ${s.nis} — ${s.kelas}`:'Cari nama atau NIS…'},pick(x,s){this[x]=s.nis;this.search[x]='';this.open[x]=false},async photo(e){try{let f=e.target.files[0];if(!f)return;if(f.size>10485760)throw Error('Ukuran file asli maksimal 10 MB.');let ext=f.name.split('.').pop().toLowerCase();if(!['jpg','jpeg','png','heic','heif'].includes(ext))throw Error('Gunakan JPG, JPEG, PNG, HEIC, atau HEIF.');this.uploading=true;this.status='Memproses foto…';let b;try{b=await createImageBitmap(f)}catch{throw Error('File bukan gambar yang dapat didekode. HEIC/HEIF memerlukan decoder browser.')}let r=Math.min(1,1600/b.width,1600/b.height),c=document.createElement('canvas');c.width=Math.round(b.width*r);c.height=Math.round(b.height*r);c.getContext('2d').drawImage(b,0,0,c.width,c.height);b.close?.();let blob=await new Promise((ok,no)=>c.toBlob(v=>v?ok(v):no(Error('Gagal mengonversi WebP.')),'image/webp',.85));if(blob.size>10485760)throw Error('Hasil WebP lebih dari 10 MB.');this.preview=URL.createObjectURL(blob);this.status='Mempersiapkan upload…';let pr=await fetch(@js(route('pilketos.kandidat.photo.presign')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':@js(csrf_token())},body:JSON.stringify({content_type:'image/webp',size:blob.size})}),d=await pr.json();if(!pr.ok)throw Error(d.message||'Gagal presign.');this.status='Mengupload foto…';await new Promise((ok,no)=>{let x=new XMLHttpRequest;x.open('PUT',d.upload_url);x.setRequestHeader('Content-Type','image/webp');x.setRequestHeader('x-amz-acl','public-read');x.upload.onprogress=v=>{if(v.lengthComputable)this.progress=Math.round(v.loaded/v.total*100)};x.onload=()=>x.status>=200&&x.status<300?ok():no(Error('Upload S3 gagal.'));x.onerror=()=>no(Error('Koneksi S3 gagal.'));x.send(blob)});this.photoKey=d.object_key;this.status='Upload selesai.'}catch(e){this.photoKey='';this.error=e.message||'Upload gagal.'}finally{this.uploading=false}},save(f){if(this.loading||this.uploading)return;if(!this.ketua||!this.wakil||+this.ketua===+this.wakil){this.error='Pilih ketua dan wakil yang berbeda.';return}f.querySelector('[name=ketua_nis]').value=this.ketua;f.querySelector('[name=wakil_nis]').value=this.wakil;this.status='Menyimpan data…';f.submit()}}}</script></body></html>
